<?php $title='Tổng quan'; ?>
<div class="page-head"><div><span class="eyebrow">WORKSPACE</span><h1><?= e($project['name']) ?></h1><p><?= $isTestEnvironment?'Quản lý các Feature được cấp trong môi trường Staging.':'Theo dõi cấu hình hiện tại của môi trường Phát hành.' ?></p></div></div>
<div class="stats-grid"><article class="stat-card"><span>Features</span><strong><?= count($flags) ?></strong><small>trong dự án</small></article><article class="stat-card"><span>Môi trường</span><strong><?= e($environment['name']??'—') ?></strong><small><?= e($environment['key']??'') ?></small></article><article class="stat-card"><span>Phiên bản hiện tại</span><strong><?= $current?'v'.(int)$current['version_number']:'—' ?></strong><small><?= e($current['status']??'Chưa phát hành') ?></small></article><article class="stat-card"><span>Features được phép chỉnh sửa</span><strong><?= count(array_filter($flags,function($flag){return (int)$flag['can_toggle']===1;})) ?></strong><small>theo dự án đang chọn</small></article></div>
<?php if(!$isTestEnvironment): ?><div class="notice info">Môi trường Phát hành chỉ xem. Chọn Staging trong thanh bên để thay đổi Feature.</div><?php endif; ?>
<?php if($isTestEnvironment && $current && $current['status']==='draft' && $hasTogglePermission): ?><section class="panel"><div class="panel-head"><div><h2>Phát hành bản nháp</h2><p>Đẩy cấu hình v<?= (int)$current['version_number'] ?> sang môi trường Phát hành.</p></div></div><form method="post" action="<?= e(url('child/publish')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="environment_id" value="<?= (int)$environmentId ?>"><input name="reason" required maxlength="500" placeholder="Lý do phát hành"><button class="button primary" type="submit" onclick="return confirm('Phát hành bản nháp v<?= (int)$current['version_number'] ?>?')">Phát hành v<?= (int)$current['version_number'] ?></button></form></section><?php endif; ?>
<section class="panel" id="features"><div class="panel-head"><div><h2>Features</h2><p><?= $current?($current['status']==='draft'?'Bản nháp v':'Phiên bản phát hành v').(int)$current['version_number']:'Chưa phát hành cấu hình' ?> · Các Feature được liệt kê theo quyền của dự án.</p></div><?php if($isTestEnvironment && $previous && $hasTogglePermission): ?><form method="post" action="<?= e(url('child/restore')) ?>" onsubmit="return confirm('Khôi phục trạng thái theo phiên bản v<?= (int)$previous['version_number'] ?>?')"><?= csrf_field() ?><input type="hidden" name="environment_id" value="<?= (int)$environmentId ?>"><button class="button" type="submit">↶ Khôi phục v<?= (int)$previous['version_number'] ?></button></form><?php endif; ?></div>
<?php if(!$flags): ?><p class="empty">Dự án chưa có Feature hoạt động.</p><?php else: ?><div class="feature-list"><?php foreach($flags as $flag): $isEnabled=(bool)$flag['kill_switch']?false:($flag['forced_value']!==null?(bool)$flag['forced_value']:(bool)$flag['default_value']); ?><div class="feature-row"><div class="feature-info"><strong><?= e($flag['name']) ?></strong><code><?= e($flag['key']) ?></code><small><?= e($flag['description']) ?></small></div><span class="pill <?= $isEnabled?'green':'gray' ?>"><?= $isEnabled?'ĐANG BẬT':'ĐANG TẮT' ?></span><?php if($isTestEnvironment && (int)$flag['can_toggle']===1): ?><form method="post" action="<?= e(url('child/toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="environment_id" value="<?= (int)$environmentId ?>"><input type="hidden" name="flag_id" value="<?= (int)$flag['id'] ?>"><input type="hidden" name="enabled" value="<?= $isEnabled?'0':'1' ?>"><button class="button <?= $isEnabled?'':'primary' ?>" type="submit"><?= $isEnabled?'Tắt':'Bật' ?></button></form><?php elseif(!$isTestEnvironment): ?><span class="pill gray">Chỉ xem · môi trường Phát hành</span><?php else: ?><span class="pill amber">Chưa được cấp quyền</span><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></section>